//! Golden-corpus tests against the original JS probability engine.
//!
//! Corpora are generated by `oracle/golden-equity.js` from
//! `reference/texas-holdem-game/js/probability-core.js` (commit e0c6c6f8 /
//! v1.5.8) and live in `tests/golden/prob/`. Exact heads-up rows must match the
//! JS numbers exactly (the same IEEE-754 operations in the same order);
//! fixed-seed Monte Carlo rows must match sample for sample (identical RNG
//! stream and draw order). `elapsedMs` is deliberately not part of the corpus.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use poker_core::{Card, Variant};
use poker_prob::{
    EquityResult, Improvements, MonteCarloOptions, calculate, exact_heads_up, find_improvements,
    monte_carlo, prepare,
};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ExactCase {
    id: String,
    variant: String,
    player: Vec<String>,
    board: Vec<String>,
    num_opponents: usize,
    result: GoldenResult,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct MonteCarloCase {
    id: String,
    variant: String,
    player: Vec<String>,
    board: Vec<String>,
    num_opponents: usize,
    simulations: u32,
    min_samples: u32,
    seed: String,
    result: GoldenResult,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ImprovementCase {
    id: String,
    variant: String,
    player: Vec<String>,
    board: Vec<String>,
    result: GoldenImprovements,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GoldenResult {
    win_prob: f64,
    tie_prob: f64,
    lose_prob: f64,
    equity_prob: f64,
    samples: u64,
    method: String,
    stats: GoldenStats,
    outs: GoldenImprovements,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GoldenStats {
    best_hand_counts: BTreeMap<String, u64>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GoldenImprovements {
    total_outs: u32,
    strong_outs: u32,
    thin_outs: u32,
    by_hand_type: BTreeMap<String, GoldenGroup>,
    note: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct GoldenGroup {
    cards: Vec<GoldenCard>,
    count: u32,
    strong_count: u32,
    thin_count: u32,
}

#[derive(Debug, Deserialize)]
struct GoldenCard {
    rank: String,
    suit: String,
    value: u8,
    quality: String,
}

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("tests")
        .join("golden")
        .join("prob")
}

fn read_jsonl<T: for<'de> Deserialize<'de>>(path: &Path) -> Vec<T> {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line)
                .unwrap_or_else(|error| panic!("bad golden line: {error}\n{line}"))
        })
        .collect()
}

fn parse_cards(case_id: &str, tokens: &[String]) -> Vec<Card> {
    tokens
        .iter()
        .map(|token| {
            token
                .parse()
                .unwrap_or_else(|error| panic!("{case_id}: bad card {token}: {error}"))
        })
        .collect()
}

fn variant_of(case_id: &str, name: &str) -> Variant {
    match name {
        "standard" => Variant::Standard,
        "shortdeck" => Variant::ShortDeck,
        other => panic!("{case_id}: unknown variant {other}"),
    }
}

fn assert_same_equity(case_id: &str, direct: &EquityResult, via_calculate: &EquityResult) {
    let mut expected = via_calculate.clone();
    expected.outs = None;
    assert_eq!(
        direct, &expected,
        "{case_id}: direct call differs from calculate"
    );
}

fn assert_result(case_id: &str, got: &EquityResult, want: &GoldenResult) {
    assert_eq!(got.method.as_str(), want.method, "{case_id}: method");
    assert_eq!(got.samples, want.samples, "{case_id}: samples");
    assert_eq!(got.win_prob, want.win_prob, "{case_id}: winProb");
    assert_eq!(got.tie_prob, want.tie_prob, "{case_id}: tieProb");
    assert_eq!(got.lose_prob, want.lose_prob, "{case_id}: loseProb");
    assert_eq!(got.equity_prob, want.equity_prob, "{case_id}: equityProb");
    assert_eq!(
        got.best_hand_counts, want.stats.best_hand_counts,
        "{case_id}: stats.bestHandCounts"
    );
    let outs = got
        .outs
        .as_ref()
        .unwrap_or_else(|| panic!("{case_id}: calculate must attach outs"));
    assert_improvements(case_id, outs, &want.outs);
}

fn assert_improvements(case_id: &str, got: &Improvements, want: &GoldenImprovements) {
    assert_eq!(got.total_outs, want.total_outs, "{case_id}: totalOuts");
    assert_eq!(got.strong_outs, want.strong_outs, "{case_id}: strongOuts");
    assert_eq!(got.thin_outs, want.thin_outs, "{case_id}: thinOuts");
    assert_eq!(got.note, want.note, "{case_id}: note");
    assert_eq!(
        got.by_hand_type.len(),
        want.by_hand_type.len(),
        "{case_id}: byHandType keys"
    );
    for (name, want_group) in &want.by_hand_type {
        let got_group = got
            .by_hand_type
            .get(name)
            .unwrap_or_else(|| panic!("{case_id}: missing hand type {name}"));
        assert_eq!(got_group.count, want_group.count, "{case_id}: {name} count");
        assert_eq!(
            got_group.strong_count, want_group.strong_count,
            "{case_id}: {name} strongCount"
        );
        assert_eq!(
            got_group.thin_count, want_group.thin_count,
            "{case_id}: {name} thinCount"
        );
        assert_eq!(
            got_group.cards.len(),
            want_group.cards.len(),
            "{case_id}: {name} cards"
        );
        for (index, (got_card, want_card)) in
            got_group.cards.iter().zip(&want_group.cards).enumerate()
        {
            assert_eq!(
                got_card.rank, want_card.rank,
                "{case_id}: {name} card {index} rank"
            );
            assert_eq!(
                got_card.suit, want_card.suit,
                "{case_id}: {name} card {index} suit"
            );
            assert_eq!(
                got_card.value, want_card.value,
                "{case_id}: {name} card {index} value"
            );
            assert_eq!(
                got_card.quality.as_str(),
                want_card.quality,
                "{case_id}: {name} card {index} quality"
            );
        }
    }
}

#[test]
fn js_golden_exact_heads_up_matches() {
    let path = golden_dir().join("exact-heads-up.jsonl");
    let cases: Vec<ExactCase> = read_jsonl(&path);
    assert_eq!(cases.len(), 6, "exact golden row count");
    for case in &cases {
        let variant = variant_of(&case.id, &case.variant);
        let player = parse_cards(&case.id, &case.player);
        let board = parse_cards(&case.id, &case.board);
        let options = MonteCarloOptions::default();
        let got = calculate(&player, &board, case.num_opponents, variant, &options)
            .unwrap_or_else(|error| panic!("{}: calculate failed: {error}", case.id));
        assert_result(&case.id, &got, &case.result);

        let prepared = prepare(&player, &board, case.num_opponents, variant)
            .unwrap_or_else(|error| panic!("{}: prepare failed: {error}", case.id));
        let direct = exact_heads_up(&prepared)
            .unwrap_or_else(|error| panic!("{}: exact failed: {error}", case.id));
        assert_same_equity(&case.id, &direct, &got);
    }
}

#[test]
fn js_golden_monte_carlo_matches() {
    let path = golden_dir().join("monte-carlo.jsonl");
    let cases: Vec<MonteCarloCase> = read_jsonl(&path);
    assert_eq!(cases.len(), 17, "monte carlo golden row count");
    for case in &cases {
        let variant = variant_of(&case.id, &case.variant);
        let player = parse_cards(&case.id, &case.player);
        let board = parse_cards(&case.id, &case.board);
        let options = MonteCarloOptions {
            seed: case.seed.clone(),
            simulations: case.simulations,
            min_samples: case.min_samples,
        };
        if case.id == "shortdeck-turn-three-way" {
            // The historical JS corpus supplied 2c on a short-deck board.
            // Preserve that evidence, but reject the impossible deal rather
            // than reproducing the oracle's meaningless equity estimate.
            assert_eq!(
                prepare(&player, &board, case.num_opponents, variant),
                Err(poker_prob::ProbError::CardOutsideVariant)
            );
            assert_eq!(
                calculate(&player, &board, case.num_opponents, variant, &options),
                Err(poker_prob::ProbError::CardOutsideVariant)
            );
            continue;
        }
        let got = calculate(&player, &board, case.num_opponents, variant, &options)
            .unwrap_or_else(|error| panic!("{}: calculate failed: {error}", case.id));
        assert_result(&case.id, &got, &case.result);

        let prepared = prepare(&player, &board, case.num_opponents, variant)
            .unwrap_or_else(|error| panic!("{}: prepare failed: {error}", case.id));
        let direct = monte_carlo(&prepared, &options);
        assert_same_equity(&case.id, &direct, &got);
    }
}

#[test]
fn js_golden_improvements_match() {
    let path = golden_dir().join("improvements.jsonl");
    let cases: Vec<ImprovementCase> = read_jsonl(&path);
    assert_eq!(cases.len(), 14, "improvements golden row count");
    for case in &cases {
        let variant = variant_of(&case.id, &case.variant);
        let player = parse_cards(&case.id, &case.player);
        let board = parse_cards(&case.id, &case.board);
        let got = find_improvements(&player, &board, variant);
        assert_improvements(&case.id, &got, &case.result);
    }
}
